# broader check: case-insensitive todo / todo-like markers anywhere in src
allhits = repo.search(r"(?i)todo|fixme|xxx|hack", glob = "src/**")
hits = ["%s:%d: %s" % (h.path, h.line, h.text.strip()) for h in allhits]
return {"files": out, "all_hits": hits}
